/* s213_own.c -- search-A, program 2 for Conjecture 213.  Shares no code with smallgraph.h or inv1.h.
 *   s213_own nt N PREFIX   every connected non-traceable graph on N <= 11 vertices, generated by
 *                          adding edges to non-path trees, keeping non-traceable graphs (complete:
 *                          a connected non-traceable graph that is not a tree loses a cycle edge and
 *                          stays connected and non-traceable).  Writes PREFIX_nt_N.txt.
 *   s213_own all NMAX      every connected graph by vertex addition (own canonical form), counts of
 *                          hypothesis graphs and non-traceable graphs.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include "mycanon.h"
#include "inv2.h"

static unsigned E[1 << 12];

static void g6_2(int n, const unsigned *adj, char *s) {
    int nb = n * (n - 1) / 2, len = (nb + 5) / 6;
    s[0] = (char)(n + 63);
    for (int i = 0; i < len; i++) s[1 + i] = 0;
    int b = 0;
    for (int j = 1; j < n; j++) for (int i = 0; i < j; i++, b++)
        if ((adj[i] >> j) & 1) s[1 + b / 6] |= (char)(1 << (5 - b % 6));
    for (int i = 0; i < len; i++) s[1 + i] += 63;
    s[1 + len] = 0;
}
static int conn2(int n, const unsigned *adj) {
    unsigned seen = 1, st = 1;
    while (st) { int v = __builtin_ctz(st); st &= st - 1; unsigned nw = adj[v] & ~seen; seen |= nw; st |= nw; }
    return seen == (1u << n) - 1;
}
static void comp2(int n, const unsigned *adj, unsigned *h) {
    for (int v = 0; v < n; v++) { h[v] = 0; for (int w = 0; w < n; w++) if (w != v && !((adj[v] >> w) & 1)) h[v] |= 1u << w; }
}

static int mode_nt(int n, const char *prefix) {
    time_t t0 = time(NULL);
    /* trees */
    mset cur; ms_init(&cur, 16);
    { unsigned a[16] = {0}; ms_add(&cur, mycanon(1, a)); }
    for (int m = 1; m < n; m++) {
        size_t c; uint64_t *L = ms_list(&cur, &c); free(cur.s);
        mset nx; ms_init(&nx, 1024);
        for (size_t i = 0; i < c; i++) {
            unsigned a[16]; mydecode(m, L[i], a);
            for (int v = 0; v < m; v++) { unsigned b[16]; memcpy(b, a, sizeof a); b[m] = 1u << v; b[v] |= 1u << m; ms_add(&nx, mycanon(m + 1, b)); }
        }
        free(L); cur = nx;
    }
    size_t ntrees; uint64_t *L = ms_list(&cur, &ntrees); free(cur.s);
    fprintf(stderr, "n=%d trees=%zu\n", n, ntrees);
    mset lev; ms_init(&lev, 1024);
    for (size_t i = 0; i < ntrees; i++) { unsigned a[16]; mydecode(n, L[i], a); if (!ham2(n, a, E)) ms_add(&lev, L[i]); }
    free(L);
    char fn[512];
    long long total = 0, hist[64] = {0}, cex = 0, nmax = 0, mhist[64] = {0}; int best = -99;
    sprintf(fn, "%s_ntmax_%d.txt", prefix, n); FILE *fm = fopen(fn, "w");
    sprintf(fn, "%s_nt_%d.txt", prefix, n); FILE *f = fopen(fn, "w");
    for (int m = n - 1; lev.cnt; m++) {
        size_t c; uint64_t *G = ms_list(&lev, &c); free(lev.s);
        mset nx; ms_init(&nx, 1 << 16);
        for (size_t i = 0; i < c; i++) {
            unsigned a[16], h[16]; mydecode(n, G[i], a);
            comp2(n, a, h);
            int g2 = gamma2_2(n, h), lm = lowmed2(n, h), sl = g2 - lm - 2;
            total++; hist[sl + 32]++; if (sl > best) best = sl;
            char s[32]; g6_2(n, a, s);
            fprintf(f, "%s %d %d %d %d\n", s, sl, g2, lm, m);
            if (sl >= 0) { cex++; printf("COUNTEREXAMPLE n=%d %s gamma2=%d lm=%d\n", n, s, g2, lm); fflush(stdout); }
            ends2(n, a, E);
            if (E[(1u << n) - 1]) { fprintf(stderr, "BUG: traceable graph in list\n"); exit(2); }
            int kids = 0;
            for (int x = 0; x < n; x++) for (int y = x + 1; y < n; y++) {
                if ((a[x] >> y) & 1) continue;
                if (ham2_plus(n, E, x, y)) continue;
                kids++;
                unsigned b[16]; memcpy(b, a, sizeof a); b[x] |= 1u << y; b[y] |= 1u << x;
                ms_add(&nx, mycanon(n, b));
            }
            if (!kids) { nmax++; mhist[sl + 32]++; fprintf(fm, "%s %d %d %d %d\n", s, sl, g2, lm, m); }
        }
        fprintf(stderr, "  edges=%d graphs=%zu (t=%lds)\n", m, c, (long)(time(NULL) - t0));
        free(G); lev = nx;
    }
    free(lev.s); fclose(f); fclose(fm);
    printf("n=%d non_traceable_connected=%lld maximal=%lld counterexamples=%lld best_slack=%d time=%lds\n   slack histogram:", n, total, nmax, cex, best, (long)(time(NULL) - t0));
    for (int s = 0; s < 64; s++) if (hist[s]) printf(" %d:%lld", s - 32, hist[s]);
    printf("\n   slack histogram of maximal ones:");
    for (int s = 0; s < 64; s++) if (mhist[s]) printf(" %d:%lld", s - 32, mhist[s]);
    printf("\n");
    return 0;
}

/* path closure (Bondy-Chvatal with threshold n-1): join non-adjacent u,v with d(u)+d(v) >= n-1 */
static void closure2(int n, unsigned *a) {
    for (int ch = 1; ch;) {
        ch = 0;
        for (int u = 0; u < n; u++) for (int v = u + 1; v < n; v++)
            if (!((a[u] >> v) & 1) && __builtin_popcount(a[u]) + __builtin_popcount(a[v]) >= n - 1) { a[u] |= 1u << v; a[v] |= 1u << u; ch = 1; }
    }
}
/* cl mode: every closed connected non-traceable graph reachable from closures of non-path trees by
 * "add an edge, take the closure"; this reaches every edge-maximal non-traceable connected graph M
 * (start at cl(T) for a spanning tree T of M; closure is monotone and cl(M) = M).  Writes the
 * maximal ones to PREFIX_clmax_N.txt.  By the slack-monotonicity lemma the largest slack over all
 * connected non-traceable graphs on N vertices is attained by a maximal one. */
static int mode_cl(int n, const char *prefix) {
    time_t t0 = time(NULL);
    mset cur; ms_init(&cur, 16);
    { unsigned a[16] = {0}; ms_add(&cur, mycanon(1, a)); }
    for (int m = 1; m < n; m++) {
        size_t c; uint64_t *L = ms_list(&cur, &c); free(cur.s);
        mset nx; ms_init(&nx, 1024);
        for (size_t i = 0; i < c; i++) {
            unsigned a[16]; mydecode(m, L[i], a);
            for (int v = 0; v < m; v++) { unsigned b[16]; memcpy(b, a, sizeof a); b[m] = 1u << v; b[v] |= 1u << m; ms_add(&nx, mycanon(m + 1, b)); }
        }
        free(L); cur = nx;
    }
    size_t ntrees; uint64_t *L = ms_list(&cur, &ntrees); free(cur.s);
    mset seen; ms_init(&seen, 1 << 16);
    size_t qcap = 1 << 16, qn = 0; uint64_t *Q = malloc(qcap * 8);
    for (size_t i = 0; i < ntrees; i++) {
        unsigned a[16]; mydecode(n, L[i], a);
        if (ham2(n, a, E)) continue;
        closure2(n, a);
        uint64_t c = mycanon(n, a);
        if (ms_add(&seen, c)) { if (qn == qcap) Q = realloc(Q, (qcap *= 2) * 8); Q[qn++] = c; }
    }
    free(L);
    char fn[512]; sprintf(fn, "%s_clmax_%d.txt", prefix, n); FILE *fm = fopen(fn, "w");
    long long total = 0, nmax = 0, cex = 0, hist[64] = {0}, mhist[64] = {0}; int best = -99;
    while (qn) {
        uint64_t code = Q[--qn];
        unsigned a[16], h[16]; mydecode(n, code, a);
        comp2(n, a, h);
        int g2 = gamma2_2(n, h), lm = lowmed2(n, h), sl = g2 - lm - 2;
        total++; hist[sl + 32]++; if (sl > best) best = sl;
        char s[32]; g6_2(n, a, s);
        if (sl >= 0) { cex++; printf("COUNTEREXAMPLE n=%d %s gamma2=%d lm=%d\n", n, s, g2, lm); fflush(stdout); }
        ends2(n, a, E);
        if (E[(1u << n) - 1]) { fprintf(stderr, "BUG: traceable graph\n"); exit(2); }
        int kids = 0;
        for (int x = 0; x < n; x++) for (int y = x + 1; y < n; y++) {
            if ((a[x] >> y) & 1) continue;
            if (ham2_plus(n, E, x, y)) continue;
            kids++;
            unsigned b[16]; memcpy(b, a, sizeof a); b[x] |= 1u << y; b[y] |= 1u << x;
            closure2(n, b);
            uint64_t c = mycanon(n, b);
            if (ms_add(&seen, c)) { if (qn == qcap) Q = realloc(Q, (qcap *= 2) * 8); Q[qn++] = c; }
        }
        if (!kids) { nmax++; mhist[sl + 32]++; int ne = 0; for (int v = 0; v < n; v++) ne += __builtin_popcount(a[v]); fprintf(fm, "%s %d %d %d %d\n", s, sl, g2, lm, ne / 2); }
    }
    fclose(fm); free(Q); free(seen.s);
    printf("n=%d closed_non_traceable_connected=%lld maximal=%lld counterexamples=%lld best_slack=%d time=%lds\n   slack histogram (closed):", n, total, nmax, cex, best, (long)(time(NULL) - t0));
    for (int s = 0; s < 64; s++) if (hist[s]) printf(" %d:%lld", s - 32, hist[s]);
    printf("\n   slack histogram (maximal):");
    for (int s = 0; s < 64; s++) if (mhist[s]) printf(" %d:%lld", s - 32, mhist[s]);
    printf("\n"); fflush(stdout);
    return 0;
}

/* u mode: closed non-traceable graphs WITH A UNIVERSAL VERTEX, from the star by "add edge, close";
 * reaches every edge-maximal non-traceable graph that has a universal vertex (it contains the star). */
static int mode_u(int n, const char *prefix) {
    time_t t0 = time(NULL);
    /* start: the star K_{1,n-1} with centre n-1 (non-traceable for n >= 4); its closure is itself */
    mset seen; ms_init(&seen, 1 << 16);
    size_t qcap = 1 << 16, qn = 0; uint64_t *Q = malloc(qcap * 8);
    { unsigned a[16] = {0}; for (int v = 0; v < n - 1; v++) { a[v] = 1u << (n - 1); a[n - 1] |= 1u << v; }
      closure2(n, a); if (!ham2(n, a, E)) { uint64_t c = mycanon(n, a); ms_add(&seen, c); Q[qn++] = c; } }
    char fn[512]; sprintf(fn, "%s_umax_%d.txt", prefix, n); FILE *fm = fopen(fn, "w");
    long long total = 0, nmax = 0, cex = 0, hist[64] = {0}, mhist[64] = {0}; int best = -99;
    while (qn) {
        uint64_t code = Q[--qn];
        unsigned a[16], h[16]; mydecode(n, code, a);
        comp2(n, a, h);
        int g2 = gamma2_2(n, h), lm = lowmed2(n, h), sl = g2 - lm - 2;
        total++; hist[sl + 32]++; if (sl > best) best = sl;
        char s[32]; g6_2(n, a, s);
        if (sl >= 0) { cex++; printf("COUNTEREXAMPLE n=%d %s gamma2=%d lm=%d\n", n, s, g2, lm); fflush(stdout); }
        ends2(n, a, E);
        if (E[(1u << n) - 1]) { fprintf(stderr, "BUG: traceable graph\n"); exit(2); }
        int kids = 0;
        for (int x = 0; x < n; x++) for (int y = x + 1; y < n; y++) {
            if ((a[x] >> y) & 1) continue;
            if (ham2_plus(n, E, x, y)) continue;
            kids++;
            unsigned b[16]; memcpy(b, a, sizeof a); b[x] |= 1u << y; b[y] |= 1u << x;
            closure2(n, b);
            uint64_t c = mycanon(n, b);
            if (ms_add(&seen, c)) { if (qn == qcap) Q = realloc(Q, (qcap *= 2) * 8); Q[qn++] = c; }
        }
        if (!kids) { nmax++; mhist[sl + 32]++; int ne = 0; for (int v = 0; v < n; v++) ne += __builtin_popcount(a[v]); fprintf(fm, "%s %d %d %d %d\n", s, sl, g2, lm, ne / 2); }
    }
    fclose(fm); free(Q); free(seen.s);
    printf("n=%d closed_non_traceable_with_universal_vertex=%lld maximal=%lld counterexamples=%lld best_slack=%d time=%lds\n   slack histogram (closed):", n, total, nmax, cex, best, (long)(time(NULL) - t0));
    for (int s = 0; s < 64; s++) if (hist[s]) printf(" %d:%lld", s - 32, hist[s]);
    printf("\n   slack histogram (maximal):");
    for (int s = 0; s < 64; s++) if (mhist[s]) printf(" %d:%lld", s - 32, mhist[s]);
    printf("\n"); fflush(stdout);
    return 0;
}

/* clp: like cl, but keeps only graphs with lm(complement) >= LMIN, i.e. um(G) <= n-1-LMIN.  um can only
 * grow when edges are added, so every closed spanning subgraph of a maximal non-traceable M with
 * lm(H_M) >= LMIN also passes: the search still reaches every such M (and every counterexample with
 * lm(H) >= LMIN, by Lemma M).  The kept graphs with no kept child are written as "terminal". */
static int lmin_g;
static int lmc(int n, const unsigned *a) { unsigned h[16]; comp2(n, a, h); return lowmed2(n, h); }
static int mode_clp(int n, const char *prefix) {
    time_t t0 = time(NULL);
    mset cur; ms_init(&cur, 16);
    { unsigned a[16] = {0}; ms_add(&cur, mycanon(1, a)); }
    for (int m = 1; m < n; m++) {
        size_t c; uint64_t *L = ms_list(&cur, &c); free(cur.s);
        mset nx; ms_init(&nx, 1024);
        for (size_t i = 0; i < c; i++) {
            unsigned a[16]; mydecode(m, L[i], a);
            for (int v = 0; v < m; v++) { unsigned b[16]; memcpy(b, a, sizeof a); b[m] = 1u << v; b[v] |= 1u << m; ms_add(&nx, mycanon(m + 1, b)); }
        }
        free(L); cur = nx;
    }
    size_t ntrees; uint64_t *L = ms_list(&cur, &ntrees); free(cur.s);
    mset seen; ms_init(&seen, 1 << 16);
    size_t qcap = 1 << 16, qn = 0; uint64_t *Q = malloc(qcap * 8);
    for (size_t i = 0; i < ntrees; i++) {
        unsigned a[16]; mydecode(n, L[i], a);
        if (ham2(n, a, E)) continue;
        closure2(n, a);
        if (lmc(n, a) < lmin_g) continue;
        uint64_t c = mycanon(n, a);
        if (ms_add(&seen, c)) { if (qn == qcap) Q = realloc(Q, (qcap *= 2) * 8); Q[qn++] = c; }
    }
    free(L);
    char fn[512]; sprintf(fn, "%s_clpterm_%d.txt", prefix, n); FILE *fm = fopen(fn, "w");
    long long total = 0, nmax = 0, cex = 0, hist[64] = {0}, mhist[64] = {0}; int best = -99;
    while (qn) {
        uint64_t code = Q[--qn];
        unsigned a[16], h[16]; mydecode(n, code, a);
        comp2(n, a, h);
        int g2 = gamma2_2(n, h), lm = lowmed2(n, h), sl = g2 - lm - 2;
        total++; hist[sl + 32]++; if (sl > best) best = sl;
        char s[32]; g6_2(n, a, s);
        if (sl >= 0) { cex++; printf("COUNTEREXAMPLE n=%d %s gamma2=%d lm=%d\n", n, s, g2, lm); fflush(stdout); }
        ends2(n, a, E);
        if (E[(1u << n) - 1]) { fprintf(stderr, "BUG: traceable graph\n"); exit(2); }
        int kids = 0;
        for (int x = 0; x < n; x++) for (int y = x + 1; y < n; y++) {
            if ((a[x] >> y) & 1) continue;
            if (ham2_plus(n, E, x, y)) continue;
            kids++;
            unsigned b[16]; memcpy(b, a, sizeof a); b[x] |= 1u << y; b[y] |= 1u << x;
            closure2(n, b);
            if (lmc(n, b) < lmin_g) continue;
            uint64_t c = mycanon(n, b);
            if (ms_add(&seen, c)) { if (qn == qcap) Q = realloc(Q, (qcap *= 2) * 8); Q[qn++] = c; }
        }
        if (!kids) { nmax++; mhist[sl + 32]++; int ne = 0; for (int v = 0; v < n; v++) ne += __builtin_popcount(a[v]); fprintf(fm, "%s %d %d %d %d\n", s, sl, g2, lm, ne / 2); }
    }
    fclose(fm); free(Q); free(seen.s);
    printf("n=%d closed_non_traceable_connected_with_lmH_ge_LMIN=%lld terminal=%lld counterexamples=%lld best_slack=%d time=%lds\n   slack histogram (closed):", n, total, nmax, cex, best, (long)(time(NULL) - t0));
    for (int s = 0; s < 64; s++) if (hist[s]) printf(" %d:%lld", s - 32, hist[s]);
    printf("\n   slack histogram (maximal):");
    for (int s = 0; s < 64; s++) if (mhist[s]) printf(" %d:%lld", s - 32, mhist[s]);
    printf("\n"); fflush(stdout);
    return 0;
}

static int mode_cc(int n, const char *prefix) {
    time_t t0 = time(NULL);
    mset cur; ms_init(&cur, 16);
    { unsigned a[16] = {0}; ms_add(&cur, mycanon(1, a)); }
    for (int m = 1; m < n; m++) {
        size_t c; uint64_t *L = ms_list(&cur, &c); free(cur.s);
        mset nx; ms_init(&nx, 1024);
        for (size_t i = 0; i < c; i++) {
            unsigned a[16]; mydecode(m, L[i], a);
            for (int v = 0; v < m; v++) { unsigned b[16]; memcpy(b, a, sizeof a); b[m] = 1u << v; b[v] |= 1u << m; ms_add(&nx, mycanon(m + 1, b)); }
        }
        free(L); cur = nx;
    }
    size_t ntrees; uint64_t *L = ms_list(&cur, &ntrees); free(cur.s);
    mset seen; ms_init(&seen, 1 << 16);
    size_t qcap = 1 << 16, qn = 0; uint64_t *Q = malloc(qcap * 8);
    for (size_t i = 0; i < ntrees; i++) {
        unsigned a[16]; mydecode(n, L[i], a);
        closure2(n, a);
        { int ne2 = 0; for (int v = 0; v < n; v++) ne2 += __builtin_popcount(a[v]); if (ne2 == n * (n - 1)) continue; }
        uint64_t c = mycanon(n, a);
        if (ms_add(&seen, c)) { if (qn == qcap) Q = realloc(Q, (qcap *= 2) * 8); Q[qn++] = c; }
    }
    free(L);
    char fn[512]; sprintf(fn, "%s_ccmax_%d.txt", prefix, n); FILE *fm = fopen(fn, "w");
    long long ntr = 0, total = 0, nmax = 0, cex = 0, hist[64] = {0}, mhist[64] = {0}; int best = -99;
    while (qn) {
        uint64_t code = Q[--qn];
        unsigned a[16], h[16]; mydecode(n, code, a);
        comp2(n, a, h);
        int g2 = gamma2_2(n, h), lm = lowmed2(n, h), sl = g2 - lm - 2;
        total++; hist[sl + 32]++; if (sl > best) best = sl;
        char s[32]; g6_2(n, a, s);
        if (sl >= 0) { cex++; printf("HYPOTHESIS_CLOSED_NONCOMPLETE n=%d %s gamma2=%d lm=%d\n", n, s, g2, lm); fflush(stdout); }
        int tr = ham2(n, a, E); if (tr) ntr++;
        int kids = 0;
        for (int x = 0; x < n; x++) for (int y = x + 1; y < n; y++) {
            if ((a[x] >> y) & 1) continue;
            unsigned b[16]; memcpy(b, a, sizeof a); b[x] |= 1u << y; b[y] |= 1u << x;
            closure2(n, b);
            { int ne2 = 0; for (int v = 0; v < n; v++) ne2 += __builtin_popcount(b[v]); if (ne2 == n * (n - 1)) continue; }
            kids++;
            uint64_t c = mycanon(n, b);
            if (ms_add(&seen, c)) { if (qn == qcap) Q = realloc(Q, (qcap *= 2) * 8); Q[qn++] = c; }
        }
        if (!kids) { nmax++; mhist[sl + 32]++; int ne = 0; for (int v = 0; v < n; v++) ne += __builtin_popcount(a[v]); fprintf(fm, "%s %d %d %d %d\n", s, sl, g2, lm, ne / 2); }
    }
    fclose(fm); free(Q); free(seen.s);
    printf("n=%d closed_connected_noncomplete=%lld (traceable %lld) maximal_closed=%lld satisfying_hypothesis=%lld best_slack=%d time=%lds\n   slack histogram (closed):", n, total, ntr, nmax, cex, best, (long)(time(NULL) - t0));
    for (int s = 0; s < 64; s++) if (hist[s]) printf(" %d:%lld", s - 32, hist[s]);
    printf("\n   slack histogram (maximal):");
    for (int s = 0; s < 64; s++) if (mhist[s]) printf(" %d:%lld", s - 32, mhist[s]);
    printf("\n"); fflush(stdout);
    return 0;
}

static int mode_all(int nmax) {
    time_t t0 = time(NULL);
    mset cur; ms_init(&cur, 16);
    { unsigned a[16] = {0}; ms_add(&cur, mycanon(1, a)); }
    for (int m = 1; m <= nmax; m++) {
        size_t c; uint64_t *L = ms_list(&cur, &c); free(cur.s);
        long long hyp = 0, nt = 0, cex = 0;
        for (size_t i = 0; i < c && m >= 2; i++) {
            unsigned a[16], h[16]; mydecode(m, L[i], a);
            comp2(m, a, h);
            int sl = gamma2_2(m, h) - lowmed2(m, h) - 2;
            if (sl >= 0) hyp++;
            if (!ham2(m, a, E)) { nt++; if (sl >= 0) cex++; }
        }
        if (m >= 2) { printf("n=%d connected=%zu hypothesis=%lld non_traceable=%lld counterexamples=%lld (t=%lds)\n", m, c, hyp, nt, cex, (long)(time(NULL) - t0)); fflush(stdout); }
        if (m == nmax) { free(L); break; }
        mset nx; ms_init(&nx, 1024);
        for (size_t i = 0; i < c; i++) {
            unsigned a[16]; mydecode(m, L[i], a);
            for (unsigned S = 1; S < (1u << m); S++) {
                unsigned b[16]; memcpy(b, a, sizeof a); b[m] = S;
                for (int v = 0; v < m; v++) if ((S >> v) & 1) b[v] |= 1u << m;
                ms_add(&nx, mycanon(m + 1, b));
            }
        }
        free(L); cur = nx;
    }
    return 0;
}

int main(int argc, char **argv) {
    if (argc >= 3 && !strcmp(argv[1], "nt")) return mode_nt(atoi(argv[2]), argc > 3 ? argv[3] : "own");
    if (argc >= 3 && !strcmp(argv[1], "all")) return mode_all(atoi(argv[2]));
    if (argc >= 4 && !strcmp(argv[1], "clp")) { lmin_g = atoi(argv[3]); return mode_clp(atoi(argv[2]), argc > 4 ? argv[4] : "own"); }
    if (argc >= 3 && !strcmp(argv[1], "u")) return mode_u(atoi(argv[2]), argc > 3 ? argv[3] : "own");
    if (argc >= 3 && !strcmp(argv[1], "cc")) return mode_cc(atoi(argv[2]), argc > 3 ? argv[3] : "own");
    if (argc >= 3 && !strcmp(argv[1], "cl")) return mode_cl(atoi(argv[2]), argc > 3 ? argv[3] : "own");
    fprintf(stderr, "usage: s213_own nt N PREFIX | all NMAX\n");
    return 1;
}
